/**
 * @file    bms_unity.c
 *
 * @brief   Unity test skeletons for the BMS module.
 *
 * Generated from bms_unit_test_checklist.md (prompt2). Bodies deferred to prompt3.
 */
#include "unity/unity.h"
#include "include_app/bms/bms.h"
#include "include_bmodule_driver_lib/crc_calc.h"

static void bms_ut_sync_roll(TIME_t local_time, BMS_DATA_BLOCK_s *db, CAN_CFG_CAN_DATA_s *can, uint32_t message_id)
{
    uint8_t crc_result;
    uint16_t i;
    can->message_id = message_id;
    for (i = 0U; i < 8U; i++)
    {
        can->data[i] = 0U;
    }
    if (message_id == 0x63BU)
    {
        can->data[0] = 65U;
        can->data[2] = 65U;
        can->data[4] = 65U;
    }
    can->data[6] = 0xFEU;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can->data, 7U, &crc_result);
    can->data[7] = (uint16_t)crc_result;
    (void)bms_read_can(local_time, db, can);
}

/* bms_init() does not touch temperature_pack; zero leftover so later tests see BSS-like state. */
static void bms_ut_zero_temperature_pack(BMS_DATA_BLOCK_s *db)
{
    db->temperature_pack.can_details.can_id = 0U;
    db->temperature_pack.can_details.timeout_value = 0U;
    db->temperature_pack.can_details.timestamp = 0U;
    db->temperature_pack.can_details.previous_timestamp = 0U;
    db->temperature_pack.can_details.fault_can_crc_message_flg = FALSE;
    db->temperature_pack.can_details.fault_can_duplicate_message_flg = FALSE;
    db->temperature_pack.can_details.fault_can_time_out_flg = FALSE;
    db->temperature_pack.can_details.fault_can_unavailble_flg = FALSE;
    db->temperature_pack.high_temperature = 0.0f;
    db->temperature_pack.low_temperature = 0.0f;
    db->temperature_pack.heatsink_temperature = 0.0f;
}

