static void test_bms_init_sets_cmd_block_to_sna(void)
{
    BMS_DATA_BLOCK_s *db;
    bms_init();
    db = bms_get();
    TEST_ASSERT_EQUAL(bms_chrg_mode_sna, db->cmd.mode);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->cmd.spd);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->cmd.cont_km1_cmd);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->cmd.cont_km2_cmd);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->cmd.cont_km3_cmd);
}

