static void test_bms_cfg_sets_seven_rx_ids_and_timeouts(void)
{
    BMS_DATA_BLOCK_s *db;
    bms_init();
    db = bms_get();
    bms_ut_zero_temperature_pack(db);
    bms_cfg();
    TEST_ASSERT_EQUAL_UINT32(0x62BU, db->current_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_UINT32(5000U, db->current_pack.can_details.timeout_value);
    TEST_ASSERT_EQUAL_UINT32(0x66BU, db->soc_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_UINT32(5000U, db->soc_pack.can_details.timeout_value);
    TEST_ASSERT_EQUAL_UINT32(0x61BU, db->status_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_UINT32(5000U, db->status_pack.can_details.timeout_value);
    TEST_ASSERT_EQUAL_UINT32(0x63BU, db->temperature_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_UINT32(5000U, db->temperature_pack.can_details.timeout_value);
    TEST_ASSERT_EQUAL_UINT32(0x64BU, db->cells_voltage_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_UINT32(5000U, db->cells_voltage_pack.can_details.timeout_value);
    TEST_ASSERT_EQUAL_UINT32(0x67BU, db->fault_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_UINT32(5000U, db->fault_pack.can_details.timeout_value);
    TEST_ASSERT_EQUAL_UINT32(0x6ABU, db->fastchr_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_UINT32(5000U, db->fastchr_pack.can_details.timeout_value);
}

