static void test_bms_read_can_marks_unavail_before_valid_rx(void)
{
    BMS_DATA_BLOCK_s *db;
    TIME_t local_time = {0U, 0U};
    CAN_CFG_CAN_DATA_s can = {0};
    uint8_t crc_result;
    boolean_t result;
    crc8_init();
    bms_init();
    db = bms_get();
    bms_ut_zero_temperature_pack(db);
    bms_cfg();
    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    can.message_id = 0x000U;
    can.data[6] = 1U;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = (uint16_t)crc_result;
    result = bms_read_can(local_time, db, &can);
    TEST_ASSERT_TRUE(result);
    TEST_ASSERT_TRUE(db->cells_voltage_pack.can_details.fault_can_unavailble_flg);
    TEST_ASSERT_TRUE(db->soc_pack.can_details.fault_can_unavailble_flg);
    TEST_ASSERT_TRUE(db->current_pack.can_details.fault_can_unavailble_flg);
    TEST_ASSERT_TRUE(db->status_pack.can_details.fault_can_unavailble_flg);
    TEST_ASSERT_TRUE(db->fault_pack.can_details.fault_can_unavailble_flg);
    TEST_ASSERT_TRUE(db->fastchr_pack.can_details.fault_can_unavailble_flg);
    TEST_ASSERT_FALSE(db->temperature_pack.can_details.fault_can_unavailble_flg);
    TEST_ASSERT_FALSE(db->temperature_pack.can_details.fault_can_time_out_flg);
    TEST_ASSERT_EQUAL_FLOAT(25.0f, db->temperature_pack.high_temperature);
    TEST_ASSERT_EQUAL_FLOAT(25.0f, db->temperature_pack.low_temperature);
    TEST_ASSERT_EQUAL_FLOAT(0.0f, db->temperature_pack.heatsink_temperature);

    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->current_pack.current);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->current_pack.ccl);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->current_pack.dcl);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->soc_pack.soc);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->soc_pack.soe);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->soc_pack.soh);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->soc_pack.capacity);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->soc_pack.pack_voltage);
    TEST_ASSERT_EQUAL(bms_kmx_sna, db->status_pack.kmx_cont[0]);
    TEST_ASSERT_EQUAL(bms_kmx_sna, db->status_pack.kmx_cont[1]);
    TEST_ASSERT_EQUAL(bms_kmx_sna, db->status_pack.kmx_cont[2]);
    TEST_ASSERT_EQUAL(bms_chrg_mode_sna, db->status_pack.mode);
    TEST_ASSERT_EQUAL(bms_chrg_sts_sna, db->status_pack.ready);
    TEST_ASSERT_EQUAL(bms_blns_sts_sna, db->status_pack.balance_status);
    TEST_ASSERT_EQUAL(bms_hvil_sna, db->status_pack.negative_hvil);
    TEST_ASSERT_EQUAL(bms_hvil_sna, db->status_pack.positive_hvil);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->status_pack.cell_cycle);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->cells_voltage_pack.highest);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->cells_voltage_pack.lowest);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->cells_voltage_pack.mean);
    TEST_ASSERT_EQUAL(bms_glob_flt_noError, db->fault_pack.global);
    TEST_ASSERT_EQUAL_UINT16((uint16_t)MAX_int16_t, db->fault_pack.code);
    TEST_ASSERT_EQUAL(bms_chrg_st_sna, db->fastchr_pack.charge_state);
    TEST_ASSERT_EQUAL(bms_contactor_sna, db->fastchr_pack.contactor);
    TEST_ASSERT_EQUAL(bms_charge_fault_sna, db->fastchr_pack.fault_code);
    TEST_ASSERT_EQUAL(bms_plug_st_sna, db->fastchr_pack.plug_state);
    TEST_ASSERT_EQUAL_UINT16((uint16_t)MAX_int16_t, db->fastchr_pack.instance_power);
    TEST_ASSERT_EQUAL_UINT16((uint16_t)MAX_int16_t, db->fastchr_pack.max_power);
    TEST_ASSERT_EQUAL_UINT16((uint16_t)MAX_int16_t, db->fastchr_pack.remain_charge_time);
}

static void test_bms_crc8_init_builds_table_for_rx(void)
{
    CAN_CFG_CAN_DATA_s can = {0};
    uint8_t crc_a;
    uint8_t crc_b;
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    TEST_ASSERT_TRUE(crc8_init());
    can.data[0] = 1U;
    crc_a = 0U;
    crc_b = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_a);
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_b);
    TEST_ASSERT_EQUAL(crc_a, crc_b);
    TEST_ASSERT_EQUAL(0xB8U, crc_a);
}

/* 5.2 Reset behavior */

static void test_bms_init_resets_to_sna_after_decode(void)
{
    BMS_DATA_BLOCK_s *db;
    TIME_t local_time = {0U, 0U};
    CAN_CFG_CAN_DATA_s can = {0};
    uint8_t crc_result;
    crc8_init();
    bms_init();
    db = bms_get();
    bms_ut_zero_temperature_pack(db);
    bms_cfg();
    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    bms_ut_sync_roll(local_time, db, &can, 0x61BU);
    bms_ut_sync_roll(local_time, db, &can, 0x62BU);
    bms_ut_sync_roll(local_time, db, &can, 0x63BU);
    bms_ut_sync_roll(local_time, db, &can, 0x64BU);
    bms_ut_sync_roll(local_time, db, &can, 0x66BU);
    bms_ut_sync_roll(local_time, db, &can, 0x67BU);
    bms_ut_sync_roll(local_time, db, &can, 0x6ABU);
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    can.message_id = 0x62BU;
    can.data[6] = 1U;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = (uint16_t)crc_result;
    (void)bms_read_can(local_time, db, &can);
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    can.message_id = 0x66BU;
    can.data[6] = 1U;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = (uint16_t)crc_result;
    (void)bms_read_can(local_time, db, &can);
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    can.message_id = 0x61BU;
    can.data[6] = 1U;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = (uint16_t)crc_result;
    (void)bms_read_can(local_time, db, &can);
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    can.message_id = 0x67BU;
    can.data[6] = 1U;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = (uint16_t)crc_result;
    (void)bms_read_can(local_time, db, &can);
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    can.message_id = 0x63BU;

    can.data[0] = 65U;
    can.data[2] = 65U;
    can.data[4] = 65U;
    can.data[6] = 1U;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = (uint16_t)crc_result;
    (void)bms_read_can(local_time, db, &can);
    bms_init();
    TEST_ASSERT_EQUAL(bms_chrg_mode_sna, db->cmd.mode);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->cmd.spd);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->cmd.cont_km1_cmd);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->cmd.cont_km2_cmd);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->cmd.cont_km3_cmd);
    TEST_ASSERT_FALSE(db->manage.ready_to_work);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->manage.fault_communication_code);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->current_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->current_pack.current);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->soc_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->soc_pack.soc);
    TEST_ASSERT_EQUAL(bms_chrg_mode_sna, db->status_pack.mode);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->cells_voltage_pack.highest);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->cells_voltage_pack.mean);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->fault_pack.code);
    TEST_ASSERT_EQUAL(bms_chrg_st_sna, db->fastchr_pack.charge_state);
    TEST_ASSERT_EQUAL_UINT32(0x63BU, db->temperature_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_UINT32(0U, db->temperature_pack.can_details.timestamp);
    TEST_ASSERT_EQUAL_FLOAT(25.0f, db->temperature_pack.high_temperature);
}

