static void test_bms_roll_counters_survive_init_for_other_packs(void)
{
    BMS_DATA_BLOCK_s *db;
    TIME_t local_time = {0U, 0U};
    CAN_CFG_CAN_DATA_s can = {0};
    uint8_t crc_result;
    uint32_t ids[6];
    uint16_t i;
    ids[0] = 0x62BU;
    ids[1] = 0x61BU;
    ids[2] = 0x63BU;
    ids[3] = 0x64BU;
    ids[4] = 0x67BU;
    ids[5] = 0x6ABU;
    for (i = 0U; i < 6U; i++)
    {
        crc8_init();
        bms_init();
        db = bms_get();
        bms_ut_zero_temperature_pack(db);
        bms_cfg();
        local_time.sec = 0U;
        local_time.up_time_ms = 0U;
        bms_ut_sync_roll(local_time, db, &can, ids[i]);
        can.message_id = 0U;
        can.data[0] = 0U;
        can.data[1] = 0U;
        can.data[2] = 0U;
        can.data[3] = 0U;
        can.data[4] = 0U;
        can.data[5] = 0U;
        can.data[6] = 0U;
        can.data[7] = 0U;
        can.message_id = ids[i];
        can.data[6] = 7U;
        crc_result = 0U;
        (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
        can.data[7] = (uint16_t)crc_result;
        (void)bms_read_can(local_time, db, &can);
        bms_init();
        db = bms_get();
        bms_ut_zero_temperature_pack(db);
        bms_cfg();
        can.message_id = 0U;
        can.data[0] = 0U;
        can.data[1] = 0U;
        can.data[2] = 0U;
        can.data[3] = 0U;
        can.data[4] = 0U;
        can.data[5] = 0U;
        can.data[6] = 0U;
        can.data[7] = 0U;
        can.message_id = ids[i];
        can.data[6] = 7U;
        crc_result = 0U;
        (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
        can.data[7] = (uint16_t)crc_result;
        (void)bms_read_can(local_time, db, &can);
        if (ids[i] == 0x62BU)
        {
            TEST_ASSERT_TRUE(db->current_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->current_pack.current);
        }
        if (ids[i] == 0x61BU)
        {
            TEST_ASSERT_TRUE(db->status_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL(bms_chrg_mode_sna, db->status_pack.mode);
        }
        if (ids[i] == 0x63BU)
        {
            TEST_ASSERT_TRUE(db->temperature_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL_FLOAT(25.0f, db->temperature_pack.high_temperature);
        }
        if (ids[i] == 0x64BU)
        {
            TEST_ASSERT_TRUE(db->cells_voltage_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL_FLOAT(4100.0f, db->cells_voltage_pack.highest);
        }
        if (ids[i] == 0x67BU)
        {
            TEST_ASSERT_TRUE(db->fault_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->fault_pack.code);
        }
        if (ids[i] == 0x6ABU)
        {
            TEST_ASSERT_TRUE(db->fastchr_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL(bms_chrg_st_sna, db->fastchr_pack.charge_state);
        }
    }
}

