static void test_bms_decode_fastchr_plug_and_contactor(void)
{
    BMS_DATA_BLOCK_s *db;
    TIME_t local_time = {0U, 0U};
    CAN_CFG_CAN_DATA_s can = {0};
    uint8_t crc_result;
    crc8_init();
    bms_init();
    db = bms_get();
    bms_ut_zero_temperature_pack(db);
    bms_cfg();
    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    bms_ut_sync_roll(local_time, db, &can, 0x61BU);
    bms_ut_sync_roll(local_time, db, &can, 0x62BU);
    bms_ut_sync_roll(local_time, db, &can, 0x63BU);
    bms_ut_sync_roll(local_time, db, &can, 0x64BU);
    bms_ut_sync_roll(local_time, db, &can, 0x66BU);
    bms_ut_sync_roll(local_time, db, &can, 0x67BU);
    bms_ut_sync_roll(local_time, db, &can, 0x6ABU);
    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    can.message_id = 0x6ABU;

    can.data[0] = (0U | (1U << 3U) | (1U << 5U));
    can.data[6] = 1U;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = (uint16_t)crc_result;
    (void)bms_read_can(local_time, db, &can);
    TEST_ASSERT_EQUAL(bms_plug_st_plug, db->fastchr_pack.plug_state);
    TEST_ASSERT_EQUAL(bms_contactor_close, db->fastchr_pack.contactor);
    local_time.sec = 0U;
    local_time.up_time_ms = 1U;
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    can.message_id = 0x6ABU;

    can.data[0] = ((2U << 3U) | (2U << 5U));
    can.data[6] = 2U;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = (uint16_t)crc_result;
    (void)bms_read_can(local_time, db, &can);
    TEST_ASSERT_EQUAL(bms_plug_st_fault, db->fastchr_pack.plug_state);
    TEST_ASSERT_EQUAL(bms_contactor_fault, db->fastchr_pack.contactor);
    local_time.sec = 0U;
    local_time.up_time_ms = 2U;
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    can.message_id = 0x6ABU;

    can.data[0] = ((3U << 3U) | (3U << 5U));
    can.data[6] = 3U;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = (uint16_t)crc_result;
    (void)bms_read_can(local_time, db, &can);
    TEST_ASSERT_EQUAL(bms_plug_st_sna, db->fastchr_pack.plug_state);
    TEST_ASSERT_EQUAL(bms_contactor_sna, db->fastchr_pack.contactor);
}

