static void test_bms_timeout_5000_rule_for_other_six_packs(void)
{
    BMS_DATA_BLOCK_s *db;
    TIME_t local_time = {0U, 0U};
    CAN_CFG_CAN_DATA_s can = {0};
    uint8_t crc_result;
    crc8_init();
    bms_init();
    db = bms_get();
    bms_ut_zero_temperature_pack(db);
    bms_cfg();
    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    bms_ut_sync_roll(local_time, db, &can, 0x61BU);
    bms_ut_sync_roll(local_time, db, &can, 0x62BU);
    bms_ut_sync_roll(local_time, db, &can, 0x63BU);
    bms_ut_sync_roll(local_time, db, &can, 0x64BU);
    bms_ut_sync_roll(local_time, db, &can, 0x66BU);
    bms_ut_sync_roll(local_time, db, &can, 0x67BU);
    bms_ut_sync_roll(local_time, db, &can, 0x6ABU);
    {
        uint32_t ids[6];
        uint32_t sib;
        uint16_t i;
        ids[0] = 0x66BU;
        ids[1] = 0x61BU;
        ids[2] = 0x64BU;
        ids[3] = 0x67BU;
        ids[4] = 0x6ABU;
        ids[5] = 0x63BU;
        for (i = 0U; i < 6U; i++)
        {
            crc8_init();
            bms_init();
            db = bms_get();
            bms_ut_zero_temperature_pack(db);
            bms_cfg();
            local_time.sec = 0U;
            local_time.up_time_ms = 0U;
            bms_ut_sync_roll(local_time, db, &can, ids[i]);
            can.message_id = 0U;
            can.data[0] = 0U;
            can.data[1] = 0U;
            can.data[2] = 0U;
            can.data[3] = 0U;
            can.data[4] = 0U;
            can.data[5] = 0U;
            can.data[6] = 0U;
            can.data[7] = 0U;
            can.message_id = ids[i];
            if (ids[i] == 0x63BU)
            {
                can.data[0] = 65U;
                can.data[2] = 65U;
                can.data[4] = 65U;
            }
            can.data[6] = 1U;
            crc_result = 0U;
            (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
            can.data[7] = (uint16_t)crc_result;
            (void)bms_read_can(local_time, db, &can);
            sib = 0x62BU;
            if (ids[i] == 0x62BU)
            {
                sib = 0x66BU;
            }
            local_time.up_time_ms = 5000U;
            can.message_id = 0U;
            can.data[0] = 0U;
            can.data[1] = 0U;
            can.data[2] = 0U;
            can.data[3] = 0U;
            can.data[4] = 0U;
            can.data[5] = 0U;
            can.data[6] = 0U;
            can.data[7] = 0U;
            can.message_id = sib;
            can.data[6] = 1U;
            crc_result = 0U;
            (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
            can.data[7] = (uint16_t)crc_result;
            (void)bms_read_can(local_time, db, &can);
            if (ids[i] == 0x66BU)
            {
                TEST_ASSERT_FALSE(db->soc_pack.can_details.fault_can_time_out_flg);
            }
            if (ids[i] == 0x61BU)
            {
                TEST_ASSERT_FALSE(db->status_pack.can_details.fault_can_time_out_flg);
            }
            if (ids[i] == 0x64BU)
            {
                TEST_ASSERT_FALSE(db->cells_voltage_pack.can_details.fault_can_time_out_flg);
            }
            if (ids[i] == 0x67BU)
            {
                TEST_ASSERT_FALSE(db->fault_pack.can_details.fault_can_time_out_flg);
            }
            if (ids[i] == 0x6ABU)
            {
                TEST_ASSERT_FALSE(db->fastchr_pack.can_details.fault_can_time_out_flg);
            }
            if (ids[i] == 0x63BU)
            {
                TEST_ASSERT_FALSE(db->temperature_pack.can_details.fault_can_time_out_flg);
            }
            local_time.up_time_ms = 5001U;
            (void)bms_read_can(local_time, db, &can);
            if (ids[i] == 0x66BU)
            {
                TEST_ASSERT_TRUE(db->soc_pack.can_details.fault_can_time_out_flg);
            }
            if (ids[i] == 0x61BU)
            {
                TEST_ASSERT_TRUE(db->status_pack.can_details.fault_can_time_out_flg);
            }
            if (ids[i] == 0x64BU)
            {
                TEST_ASSERT_TRUE(db->cells_voltage_pack.can_details.fault_can_time_out_flg);
            }
            if (ids[i] == 0x67BU)
            {
                TEST_ASSERT_TRUE(db->fault_pack.can_details.fault_can_time_out_flg);
            }
            if (ids[i] == 0x6ABU)
            {
                TEST_ASSERT_TRUE(db->fastchr_pack.can_details.fault_can_time_out_flg);
            }
            if (ids[i] == 0x63BU)
            {
                TEST_ASSERT_TRUE(db->temperature_pack.can_details.fault_can_time_out_flg);
            }
        }
    }
}

