/* 5.13 Fault / error handling */

static void test_bms_read_can_skips_dup_check_on_crc_fail(void)
{
    BMS_DATA_BLOCK_s *db;
    TIME_t local_time = {0U, 0U};
    CAN_CFG_CAN_DATA_s can = {0};
    uint8_t crc_result;
    crc8_init();
    bms_init();
    db = bms_get();
    bms_ut_zero_temperature_pack(db);
    bms_cfg();
    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    can.message_id = 0U;
    can.data[0] = 0U;
    can.data[1] = 0U;
    can.data[2] = 0U;
    can.data[3] = 0U;
    can.data[4] = 0U;
    can.data[5] = 0U;
    can.data[6] = 0U;
    can.data[7] = 0U;
    can.message_id = 0x66BU;
    can.data[6] = 1U;
    crc_result = 0U;
    (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
    can.data[7] = (uint16_t)(crc_result + 1U);
    (void)bms_read_can(local_time, db, &can);
    TEST_ASSERT_TRUE(db->soc_pack.can_details.fault_can_crc_message_flg);
    TEST_ASSERT_FALSE(db->soc_pack.can_details.fault_can_duplicate_message_flg);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->soc_pack.can_details.timestamp);
}

static void test_bms_read_can_crc_fail_independent_per_pack(void)
{
    BMS_DATA_BLOCK_s *db;
    TIME_t local_time = {0U, 0U};
    CAN_CFG_CAN_DATA_s can = {0};
    uint8_t crc_result;
    crc8_init();
    bms_init();
    db = bms_get();
    bms_ut_zero_temperature_pack(db);
    bms_cfg();
    local_time.sec = 0U;
    local_time.up_time_ms = 0U;
    {
        uint32_t ids[7];
        uint16_t i;
        ids[0] = 0x62BU;
        ids[1] = 0x66BU;
        ids[2] = 0x61BU;
        ids[3] = 0x63BU;
        ids[4] = 0x64BU;
        ids[5] = 0x67BU;
        ids[6] = 0x6ABU;
        for (i = 0U; i < 7U; i++)
        {
            crc8_init();
            bms_init();
            db = bms_get();
            bms_ut_zero_temperature_pack(db);
            bms_cfg();
            local_time.sec = 0U;
            local_time.up_time_ms = 0U;
            can.message_id = 0U;
            can.data[0] = 0U;
            can.data[1] = 0U;
            can.data[2] = 0U;
            can.data[3] = 0U;
            can.data[4] = 0U;
            can.data[5] = 0U;
            can.data[6] = 0U;
            can.data[7] = 0U;
            can.message_id = ids[i];
            can.data[6] = 1U;
            crc_result = 0U;
            (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
            can.data[7] = (uint16_t)(crc_result + 1U);
            (void)bms_read_can(local_time, db, &can);
            if (ids[i] == 0x62BU)
            {
                TEST_ASSERT_TRUE(db->current_pack.can_details.fault_can_crc_message_flg);
            }
            if (ids[i] == 0x66BU)
            {
                TEST_ASSERT_TRUE(db->soc_pack.can_details.fault_can_crc_message_flg);
            }
            if (ids[i] == 0x61BU)
            {
                TEST_ASSERT_TRUE(db->status_pack.can_details.fault_can_crc_message_flg);
            }
            if (ids[i] == 0x63BU)
            {
                TEST_ASSERT_TRUE(db->temperature_pack.can_details.fault_can_crc_message_flg);
            }
            if (ids[i] == 0x64BU)
            {
                TEST_ASSERT_TRUE(db->cells_voltage_pack.can_details.fault_can_crc_message_flg);
            }
            if (ids[i] == 0x67BU)
            {
                TEST_ASSERT_TRUE(db->fault_pack.can_details.fault_can_crc_message_flg);
            }
            if (ids[i] == 0x6ABU)
            {
                TEST_ASSERT_TRUE(db->fastchr_pack.can_details.fault_can_crc_message_flg);
            }
        }
    }
}

static void test_bms_read_can_duplicate_independent_per_pack(void)
{
    BMS_DATA_BLOCK_s *db;
    TIME_t local_time = {0U, 0U};
    CAN_CFG_CAN_DATA_s can = {0};
    uint8_t crc_result;
    uint32_t ids[7];
    uint16_t i;
    ids[0] = 0x62BU;
    ids[1] = 0x66BU;
    ids[2] = 0x61BU;
    ids[3] = 0x63BU;
    ids[4] = 0x64BU;
    ids[5] = 0x67BU;
    ids[6] = 0x6ABU;
    for (i = 0U; i < 7U; i++)
    {
        crc8_init();
        bms_init();
        db = bms_get();
        bms_ut_zero_temperature_pack(db);
        bms_cfg();
        local_time.sec = 0U;
        local_time.up_time_ms = 0U;
        bms_ut_sync_roll(local_time, db, &can, ids[i]);
        can.message_id = 0U;
        can.data[0] = 0U;
        can.data[1] = 0U;
        can.data[2] = 0U;
        can.data[3] = 0U;
        can.data[4] = 0U;
        can.data[5] = 0U;
        can.data[6] = 0U;
        can.data[7] = 0U;
        can.message_id = ids[i];
        if (ids[i] == 0x66BU)
        {
            can.data[0] = 20U;
        }
        if (ids[i] == 0x61BU)
        {
            can.data[0] = 1U;
        }
        if (ids[i] == 0x63BU)
        {
            can.data[0] = 65U;
            can.data[2] = 65U;
            can.data[4] = 65U;
        }
        if (ids[i] == 0x64BU)
        {
            can.data[0] = 0xE8U;
            can.data[1] = 0x03U;
        }
        if (ids[i] == 0x67BU)
        {
            can.data[4] = 10U;
        }
        if (ids[i] == 0x6ABU)
        {
            can.data[0] = 1U;
        }
        can.data[6] = 1U;
        crc_result = 0U;
        (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
        can.data[7] = (uint16_t)crc_result;
        (void)bms_read_can(local_time, db, &can);
        local_time.up_time_ms = 1U;
        if (ids[i] == 0x66BU)
        {
            can.data[0] = 80U;
        }
        if (ids[i] == 0x61BU)
        {
            can.data[0] = 2U;
        }
        if (ids[i] == 0x63BU)
        {
            can.data[0] = 40U;
        }
        if (ids[i] == 0x64BU)
        {
            can.data[0] = 0xD0U;
            can.data[1] = 0x07U;
        }
        if (ids[i] == 0x67BU)
        {
            can.data[4] = 11U;
        }
        if (ids[i] == 0x6ABU)
        {
            can.data[0] = 3U;
        }
        if (ids[i] == 0x62BU)
        {
            can.data[0] = 0x10U;
            can.data[1] = 0x27U;
        }
        can.data[6] = 1U;
        crc_result = 0U;
        (void)crc_calc_crc8((uint8_t *)can.data, 7U, &crc_result);
        can.data[7] = (uint16_t)crc_result;
        (void)bms_read_can(local_time, db, &can);
        if (ids[i] == 0x62BU)
        {
            TEST_ASSERT_TRUE(db->current_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL_FLOAT(-1000.0f, db->current_pack.current);
        }
        if (ids[i] == 0x66BU)
        {
            TEST_ASSERT_TRUE(db->soc_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL_FLOAT(10.0f, db->soc_pack.soc);
        }
        if (ids[i] == 0x61BU)
        {
            TEST_ASSERT_TRUE(db->status_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL(bms_chrg_mode_discharge, db->status_pack.mode);
        }
        if (ids[i] == 0x63BU)
        {
            TEST_ASSERT_TRUE(db->temperature_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL_FLOAT(25.0f, db->temperature_pack.high_temperature);
        }
        if (ids[i] == 0x64BU)
        {
            TEST_ASSERT_TRUE(db->cells_voltage_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL_FLOAT(1000.0f, db->cells_voltage_pack.highest);
        }
        if (ids[i] == 0x67BU)
        {
            TEST_ASSERT_TRUE(db->fault_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL_UINT16(10U, db->fault_pack.code);
        }
        if (ids[i] == 0x6ABU)
        {
            TEST_ASSERT_TRUE(db->fastchr_pack.can_details.fault_can_duplicate_message_flg);
            TEST_ASSERT_EQUAL(bms_chrg_st_isolation, db->fastchr_pack.charge_state);
        }
    }
}

