    TEST_ASSERT_EQUAL(bms_chrg_mode_powerUp, db->status_pack.mode);
    TEST_ASSERT_EQUAL(bms_chrg_sts_notReady, db->status_pack.ready);
    TEST_ASSERT_EQUAL(bms_kmx_notAvailable, db->status_pack.kmx_cont[0]);
    TEST_ASSERT_EQUAL(bms_hvil_open, db->status_pack.positive_hvil);
    TEST_ASSERT_EQUAL(bms_blns_sts_inactive, db->status_pack.balance_status);
