static void test_bms_init_skips_temperature_pack(void)
{
    BMS_DATA_BLOCK_s *db;
    db = bms_get();
    bms_ut_zero_temperature_pack(db);
    bms_init();
    db = bms_get();
    TEST_ASSERT_EQUAL_UINT32(0U, db->temperature_pack.can_details.can_id);
    TEST_ASSERT_EQUAL_UINT32(0U, db->temperature_pack.can_details.timeout_value);
    TEST_ASSERT_EQUAL_UINT32(0U, db->temperature_pack.can_details.timestamp);
    TEST_ASSERT_EQUAL_UINT32(0U, db->temperature_pack.can_details.previous_timestamp);
    TEST_ASSERT_FALSE(db->temperature_pack.can_details.fault_can_crc_message_flg);
    TEST_ASSERT_FALSE(db->temperature_pack.can_details.fault_can_duplicate_message_flg);
    TEST_ASSERT_FALSE(db->temperature_pack.can_details.fault_can_time_out_flg);
    TEST_ASSERT_FALSE(db->temperature_pack.can_details.fault_can_unavailble_flg);
    TEST_ASSERT_EQUAL_FLOAT(0.0f, db->temperature_pack.high_temperature);
    TEST_ASSERT_EQUAL_FLOAT(0.0f, db->temperature_pack.low_temperature);
    TEST_ASSERT_EQUAL_FLOAT(0.0f, db->temperature_pack.heatsink_temperature);
}

